mapper.select:
select dwi.*,dwr.rel_type, WM_CONCAT(dwr.rel_id) rel_ids GROUP_CONCAT(dwr.rel_id) rel_ids string_agg(dwr.rel_id,',') rel_ids from dete_warn_info dwi,dete_warn_rel dwr where dwi.del_flag='0' and dwr.del_flag='0' and dwi.id=dwr.warn_id
and dwi.name like '%'||#{name}||'%' concat('%',#{name},'%') concat('%',#{name},'%')
and dwr.rel_type='1' and dwr.rel_id=#{typeId}
and dwr.rel_type='2' and dwr.rel_id=#{setId}
and ( (dwi.view_level='1' and dwi.id in(select pmi.type_id from permission_info pmi, (SELECT ug.group_id FROM user_usergroup ug WHERE ug.user_id = #{user}) uug where pmi.view_level='1' and pmi.type='2' and pmi.rel_id=uug.group_id)) or (dwi.view_level='2' and dwi.id in (select pmi.type_id from permission_info pmi where pmi.view_level='2' and pmi.rel_id=#{system})) or (dwi.view_level='3') ) group by dwi.id
order by #{sidx}
#{order}
limit #{start},#{pageSize}

select count(1) from ( select dwi.*,dwr.rel_type, WM_CONCAT(dwr.rel_id) rel_ids GROUP_CONCAT(dwr.rel_id) rel_ids string_agg(dwr.rel_id,',') rel_ids from dete_warn_info dwi,dete_warn_rel dwr where dwi.del_flag='0' and dwr.del_flag='0' and dwi.id=dwr.warn_id
and dwi.name like '%'||#{name}||'%' concat('%',#{name},'%') concat('%',#{name},'%')
and dwr.rel_type='1' and dwr.rel_id=#{typeId}
and dwr.rel_type='2' and dwr.rel_id=#{setId}
and ( (dwi.view_level='1' and dwi.id in(select pmi.type_id from permission_info pmi, (SELECT ug.group_id FROM user_usergroup ug WHERE ug.user_id = #{user}) uug where pmi.view_level='1' and pmi.type='2' and pmi.rel_id=uug.group_id)) or (dwi.view_level='2' and dwi.id in (select pmi.type_id from permission_info pmi where pmi.view_level='2' and pmi.rel_id=#{system})) or (dwi.view_level='3') ) group by dwi.id) t
